from pathlib import Path
import subprocess,json,hashlib,statistics,time,fcntl
from check_output import answers
p=Path(__file__).parent;b=p/'baseline';o=p/'final_performance';o.mkdir(exist_ok=True)
variants={'baseline':p/'baseline/Geometry/Nearest_Two_points.cpp','control':p/'baseline/Geometry/Nearest_Two_points.cpp','final':p/'final.hpp'}
main=(b/'Verify/current/drivers/nearest_two_points_main.cpp').read_text().replace('#include "Verify/current/common/fast_io.hpp"',(b/'Verify/current/common/fast_io.hpp').read_text());modes={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};builds=[]
for name,src in variants.items():(o/(name+'.hpp')).write_bytes(src.read_bytes());(o/(name+'.cpp')).write_text('#define SKIP_RUNTIME_CHECKS\n'+src.read_text()+main)
for mode,cc in modes.items():
 for name,src in variants.items():
  cmd=[*cc,'-std=c++23','-O2',str(o/(name+'.cpp')),'-o',str(o/(mode+'_'+name))];subprocess.run(['taskset','-c','6',*cmd],capture_output=True,check=True);builds.append({'mode':mode,'variant':name,'command':cmd,'header_sha256':hashlib.sha256((o/(name+'.hpp')).read_bytes()).hexdigest()})
cases=[p/'official'/c for c in ['max_random_00.in','max_random_01.in','max_colinear_00.in','near_grid_00.in','near_circle_00.in','small_random_00.in','all_same_00.in','mid_random_00.in']]
inputs={c.name:c.read_bytes()for c in cases};refs={c.name:answers(inputs[c.name],(p/'reference_outputs'/(c.name+'.out')).read_bytes())for c in cases}

raw={m:{v:{c.name:[]for c in cases}for v in variants}for m in modes};cache={};outputs={}
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 print('waiting lock',flush=True);fcntl.flock(lock,fcntl.LOCK_EX)
 for rep in range(7):
  for m in modes:
   for c in cases:
    names=list(variants);names=names[rep%len(names):]+names[:rep%len(names)]
    for v in names:
     start=time.perf_counter_ns();out=subprocess.check_output(['taskset','-c','14',str(o/(m+'_'+v))],input=inputs[c.name]);ms=(time.perf_counter_ns()-start)/1e6;digest=hashlib.sha256(out).hexdigest();key=(c.name,digest)
     if key not in cache:assert answers(inputs[c.name],out)==refs[c.name];cache[key]=True
     raw[m][v][c.name].append(ms);outputs.setdefault(m,{}).setdefault(v,{})[c.name]=digest
  print('round',rep,'done',flush=True)
med={m:{v:{c:statistics.median(xs)for c,xs in cs.items()}for v,cs in vs.items()}for m,vs in raw.items()};ratios={m:{v:{c:t/vs['baseline'][c]for c,t in cs.items()}for v,cs in vs.items()}for m,vs in med.items()}
(o/'results.json').write_text(json.dumps({'raw_ms':raw,'medians_ms':med,'ratios':ratios,'builds':builds,'outputs':outputs,'expected_squared_distances':refs,'repetitions':7,'cpu_affinity':14,'note':'同一main/IO/flags/checks。異なる正解を許すため長さと添字・値の順序を検査。検査と参照は計時外。同じ入力/出力SHAの再検査は省く。'},indent=2)+'\n')
for m,vs in ratios.items():
 for v,cs in vs.items():print(m,v,{c:round(x,3)for c,x in cs.items()},flush=True)

