def answers(data,output):
 it=iter(map(int,data.split()));tests=next(it);ids=list(map(int,output.split()));assert len(ids)==tests*2;distances=[]
 for k in range(tests):
  n=next(it);a=[(next(it),next(it))for _ in range(n)];i,j=ids[2*k:2*k+2];assert 0<=i<n and 0<=j<n and i!=j
  distances.append((a[i][0]-a[j][0])**2+(a[i][1]-a[j][1])**2)
 try:next(it);raise AssertionError('extra input')
 except StopIteration:pass
 return distances

