from pathlib import Path
import sys
s=Path(sys.argv[1]).read_text();s=s.replace('    using Distance = unsigned __int128;','    __extension__ using Distance = unsigned __int128;')
old='    template<std::input_iterator Iterator, std::sentinel_for<Iterator> Sentinel>\n    static std::optional<NearestTwoPointsResult> run(Iterator first, Sentinel last) {'
new='    template<bool Sorted = false, std::input_iterator Iterator, std::sentinel_for<Iterator> Sentinel>\n    static std::optional<NearestTwoPointsResult> run(Iterator first, Sentinel last) {'
assert old in s;s=s.replace(old,new)
mark='            solver.nodes_.push_back({static_cast<std::int32_t>(point.first),'
assert mark in s;s=s.replace(mark,'''#ifndef SKIP_RUNTIME_CHECKS
            if constexpr (Sorted) {
                if (!solver.nodes_.empty()) {
                    const auto& previous = solver.nodes_.back();
                    if (static_cast<std::int32_t>(point.first) < previous.x ||
                        (static_cast<std::int32_t>(point.first) == previous.x &&
                         static_cast<std::int32_t>(point.second) < previous.y))
                        throw std::invalid_argument("nearest_two_points_sorted: unordered input");
                }
            }
#endif
'''+mark)
marker='        if (solver.nodes_.size() < 2) return std::nullopt;'
a=s.index(marker)+len(marker);b=s.index('        solver.best_ =',a)
s=s[:a]+'\n        if constexpr (!Sorted) {\n'+''.join('    '+line if line.strip()else line for line in s[a:b].splitlines(keepends=True))+'        }\n'+s[b:]
s=s.replace('NearestTwoPointsSolver::run(first, last)','NearestTwoPointsSolver::run(std::move(first), std::move(last))').replace('std::counted_iterator(first, count)','std::counted_iterator(std::move(first), count)').replace('nearest_two_points(first, static_cast<std::ptrdiff_t>(n))','nearest_two_points(std::move(first), static_cast<std::ptrdiff_t>(n))')
s+='''
#ifndef SIRKIT_NEAREST_TWO_POINTS_SORTED_DEFINED
#define SIRKIT_NEAREST_TWO_POINTS_SORTED_DEFINED
// 整列済み[first,last)版: (x,y)辞書順の非減少を前提に初回sortを省く。検査時はコピー中に順序を確認。
// 戻り値はnearest_two_pointsと同じで、添字は渡した列内。O(N log N)時間/O(N)領域、入力不変。
template<std::input_iterator Iterator, std::sentinel_for<Iterator> Sentinel>
std::optional<NearestTwoPointsResult> nearest_two_points_sorted(Iterator first, Sentinel last) {
    return reinsirk::detail::NearestTwoPointsSolver::run<true>(std::move(first), std::move(last));
}
// 整列済みfirstからcount個の版。count>=0かつ指定個数を参照可能。戻り値・計算量は範囲版と同じ。
template<std::input_iterator Iterator>
std::optional<NearestTwoPointsResult> nearest_two_points_sorted(Iterator first, std::ptrdiff_t count) {
#ifndef SKIP_RUNTIME_CHECKS
    if (count < 0) throw std::invalid_argument("nearest_two_points_sorted: negative count");
#endif
    return nearest_two_points_sorted(std::counted_iterator(std::move(first), count), std::default_sentinel);
}
// 整列済みvector全体版。戻り値・前提・計算量は範囲版と同じ。
template<class Point, class Allocator>
std::optional<NearestTwoPointsResult> nearest_two_points_sorted(const std::vector<Point, Allocator>& points) {
    return nearest_two_points_sorted(points.begin(), points.end());
}
#endif
'''
s=s.replace('    static Distance square(std::uint64_t d) { return Distance(d * d); }','    // 差はUINT32_MAX以下なので、単独の二乗は64bitに収まる。\n    static Distance square(std::uint64_t d) { return Distance(d * d); }')
s=s.replace('    void sort_by_x() {','    // 大入力では符号bitを反転したxを基数整列する。\n    void sort_by_x() {')
s=s.replace('    void solve(Node* input, Node* output,','    // 同区間の両配列をx順で開始し、outputをy順で返す。inputは作業用。\n    void solve(Node* input, Node* output,')
s=s.replace('            solver.buffer_ = solver.nodes_;','            // 最初だけ両配列のx順を揃える。\n            solver.buffer_ = solver.nodes_;')
Path(sys.argv[2]).write_text(s)

