p=Path(__file__).parent;s=(p.parent/'baseline/Geometry/Nearest_Two_points.cpp').read_text();s=s.replace('using Distance = unsigned __int128;','__extension__ using Distance = unsigned __int128;');(p/'baseline.hpp').write_text(s);(p/'control.hpp').write_text(s)
narrow=s.replace('return Distance(d) * d;','return Distance(d * d);');(p/'square.hpp').write_text(narrow)
unique=narrow.replace('#include <limits>','#include <limits>\n#include <memory>').replace('std::vector<Node> buffer_;','std::unique_ptr<Node[]> buffer_;').replace('buffer_.begin()', 'buffer_.get()').replace('solver.buffer_.resize(solver.nodes_.size());','solver.buffer_ = std::make_unique_for_overwrite<Node[]>(solver.nodes_.size());');(p/'unique.hpp').write_text(unique)
for cutoff in [8,16,32]:(p/f'cutoff{cutoff}.hpp').write_text(unique.replace('right - left <= 3',f'right - left <= {cutoff}'))
start=narrow.index('    void solve(std::size_t left, std::size_t right) {');end=narrow.index('\n\npublic:',start)
solve='''    void solve(Node* input, Node* output, std::size_t left, std::size_t right) {
        if (zero_) return;
        if (right - left <= 8) {
            for (auto i = left; i < right; ++i)
                for (auto j = i + 1; j < right; ++j) update(output[i], output[j]);
            std::sort(output + left, output + right, by_y);
            return;
        }
        const auto middle = left + (right - left) / 2;
        const auto split_x = input[middle].x;
        solve(output, input, left, middle);
        solve(output, input, middle, right);
        if (zero_) return;
        std::merge(input + left, input + middle, input + middle, input + right, output + left, by_y);
        auto used = left;
        for (auto i = left; i < right; ++i) {
            const Node current = output[i];
            if (!(square(difference(current.x, split_x)) < best_)) continue;
            for (auto j = used; j > left;) {
                const Node& previous = input[--j];
                if (!(square(difference(current.y, previous.y)) < best_)) break;
                update(current, previous);
                if (zero_) return;
            }
            input[used++] = current;
        }
    }'''
