#include SOURCE
#include <boost/multiprecision/cpp_int.hpp>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <random>
#include <vector>
using B=boost::multiprecision::cpp_int;
static std::uint64_t checks=0;
static void require(bool ok){++checks;if(!ok)std::abort();}
static B dist(P a,P b){B x=B(a.first)-b.first,y=B(a.second)-b.second;return x*x+y*y;}
static void inspect(const std::vector<P>&v){const auto old=v;B best=0;for(std::size_t i=0;i<v.size();++i)for(std::size_t j=0;j<i;++j){const auto d=dist(v[i],v[j]);if((i==1&&j==0)||d<best)best=d;}
 bool threw=false;std::optional<NearestTwoPointsResult> got;try{got=nearest_two_points(v);}catch(const std::overflow_error&){threw=true;}
 require(v==old);if(v.size()<2){require(!got&&!threw);return;}require(threw==(best>std::numeric_limits<std::uint64_t>::max()));if(threw)return;
 require(got.has_value());require(got->first_index<got->second_index&&got->second_index<v.size());require(B(got->distance_squared)==best);require(dist(v[got->first_index],v[got->second_index])==best);
}
int main(){std::mt19937_64 rng(812731);for(int test=0;test<2000;++test){std::vector<P>v(test%79);for(auto&[x,y]:v){x=static_cast<std::int32_t>(rng());y=static_cast<std::int32_t>(rng());if(test%3==0){x%=99;y%=99;}if(test%5==0)y=x;if(test%7==0)x=1;}inspect(v);}
 for(int n:{2047,2048,2049,4097}){std::vector<P> v(n);for(auto&[x,y]:v){x=static_cast<std::int32_t>(rng());y=static_cast<std::int32_t>(rng());}inspect(v);}
 for(int mode=0;mode<2;++mode){std::vector<P> v(2112);for(std::size_t i=0;i<v.size();++i){v[i].first=mode?static_cast<std::int32_t>((i%4)*65536-131072):7;v[i].second=static_cast<std::int32_t>(rng());}inspect(v);}
 const std::int32_t low=std::numeric_limits<std::int32_t>::min(),high=std::numeric_limits<std::int32_t>::max();std::vector<P>ends={{low,low},{high,high},{low,high},{high,low},{0,0},{0,1}};for(unsigned mask=0;mask<(1u<<ends.size());++mask){std::vector<P>v;for(std::size_t i=0;i<ends.size();++i)if(mask>>i&1)v.push_back(ends[i]);inspect(v);}
 std::printf("PASS %ju cpp_int checks\n",static_cast<std::uintmax_t>(checks));}

