#include SOURCE
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <random>
#include <string>
#include <vector>
static void barrier(){std::atomic_signal_fence(std::memory_order_seq_cst);}
static std::vector<P> prepare(const std::string&shape){std::mt19937_64 rng(812731);const int n=shape=="tiny"?16:200000;std::vector<P>v(n);for(int i=0;i<n;++i){auto&[x,y]=v[i];if(shape=="grid"){x=(i%500)*997;y=(i/500)*991;}else if(shape=="line"){x=i*997;y=i*701;}else if(shape=="vertical"){x=7;y=i*701;}else{x=static_cast<std::int32_t>(rng());y=static_cast<std::int32_t>(rng());if(shape!="wide"){x%=1000000000;y%=1000000000;}}if(shape=="duplicates"&&i%128==0)x=y=0;}return v;}
[[gnu::noinline]]static NearestTwoPointsResult run(const std::vector<P>&v){barrier();const auto out=*nearest_two_points(v);barrier();return out;}
