static void barrier(){std::atomic_signal_fence(std::memory_order_seq_cst);}
static void require(bool ok){if(!ok)std::abort();}
static std::vector<P> prepare(const std::string& shape,std::size_t n){std::mt19937_64 rng(512719);std::vector<P>v(n);for(std::size_t i=0;i<n;++i){auto&[x,y]=v[i];if(shape=="grid"){x=static_cast<std::int32_t>(i%503)*997;y=static_cast<std::int32_t>(i/503)*991;}else if(shape=="vertical"){x=7;y=static_cast<std::int32_t>(i)*701;}else{x=static_cast<std::int32_t>(rng()%2000000001)-1000000000;y=static_cast<std::int32_t>(rng()%2000000001)-1000000000;}}std::sort(v.begin(),v.end());return v;}
static std::uint64_t distance(P a,P b){const std::int64_t dx=std::int64_t(a.first)-b.first,dy=std::int64_t(a.second)-b.second;return static_cast<std::uint64_t>(dx*dx+dy*dy);}
static void inspect(const std::vector<P>&v){auto before=v;const auto a=*nearest_two_points(v);const auto b=*nearest_two_points_sorted(v);require(a.distance_squared==b.distance_squared);for(const auto r:{a,b}){require(r.first_index<r.second_index&&r.second_index<v.size());require(distance(v[r.first_index],v[r.second_index])==r.distance_squared);}require(v==before);}
template<bool Sorted>[[gnu::noinline]]static NearestTwoPointsResult run(const std::vector<P>&v){barrier();const auto out=Sorted?nearest_two_points_sorted(v):nearest_two_points(v);barrier();return *out;}
template<bool Sorted>static void measure(const std::string&key,const std::vector<P>&v,std::size_t count){std::uint64_t distance_sum=0,index_sum=0;barrier();const auto begin=std::chrono::steady_clock::now();for(std::size_t i=0;i<count;++i){const auto out=run<Sorted>(v);distance_sum+=out.distance_squared;index_sum+=out.first_index+out.second_index;}const auto end=std::chrono::steady_clock::now();barrier();const double ns=std::chrono::duration<double,std::nano>(end-begin).count()/count;std::printf("%s %.9f %zu %ju %ju\n",key.c_str(),ns,count,static_cast<std::uintmax_t>(distance_sum),static_cast<std::uintmax_t>(index_sum));}
int main(int argc,char**argv){const std::string mode=argc>1?argv[1]:"check";std::map<std::string,std::size_t> counts;if(argc>2){std::ifstream in(argv[2]);std::string key;std::size_t count;while(in>>key>>count)counts[key]=count;}
 for(const auto n:{std::size_t{32},std::size_t{2048},std::size_t{200000}})for(const auto* shape:{"random","grid","vertical"}){const auto v=prepare(shape,n);const auto key=std::string(shape)+":"+std::to_string(n);if(mode=="check"){inspect(v);std::printf("PASS %s sorted/input/result checks\n",key.c_str());}else{const auto count=mode=="calibrate"?1:counts.at(key);if(mode=="sorted")measure<true>(key,v,count);else measure<false>(key,v,count);}}
}

