#ifndef SIRKIT_INTERNAL_NEAREST_TWO_POINTS_DEFINED
#define SIRKIT_INTERNAL_NEAREST_TWO_POINTS_DEFINED
namespace reinsirk::detail {
class NearestTwoPointsSolver {
    struct Node {
        std::int32_t x;
        std::int32_t y;
        std::size_t index;
    };
