            solver.buffer_ = std::make_unique_for_overwrite<Node[]>(solver.nodes_.size());
            solver.solve(0, solver.nodes_.size());
        }
        return NearestTwoPointsResult{narrow(solver.best_), solver.best_first_, solver.best_second_};
    }
