        const auto middle = left + (right - left) / 2;
        const auto split_x = nodes_[middle].x;
        solve(left, middle);
        solve(middle, right);
        if (zero_) return;
        std::merge(nodes_.begin() + left, nodes_.begin() + middle,
                   nodes_.begin() + middle, nodes_.begin() + right,
                   buffer_.get() + left, by_y);
        std::copy(buffer_.get() + left, buffer_.get() + right, nodes_.begin() + left);
