        for (const auto& node : nodes_) {
            const auto key = static_cast<std::uint32_t>(node.x) ^ UINT32_C(0x80000000);
            for (unsigned pass = 0; pass < 4; ++pass) ++counts[pass][(key >> (pass * 8)) & 255U];
        }
